const TAX_RATE = 0.21;

function subtotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}

function total(items, { discount = 0 } = {}) {
  const sum = subtotal(items) - discount;
  return sum + sum * TAX_RATE;
}

